import { expect, test as unprotectedTest, type WorkerInfo } from '@playwright/test';
import { dirname, join, resolve } from 'node:path';
import { tmpdir } from 'node:os';
import { mkdtempSync, promises as fsPromises, readFileSync, rmSync, writeFileSync } from 'node:fs';
import {
  test as privateTest,
  requirePrivateArtifacts,
  sanitizeTestErrors,
} from '../fixtures/artifact-privacy';
import { assistantPermissionCodes } from '../fixtures/assistant-permissions';

// Public marker is generated by the control launcher; never a user's credential.
const marker = process.env.RCT_E2E_CONTROL_MARKER!;
// Public-marker red control reproduces the original base/afterEach boundary only.
const test = process.env.RCT_E2E_CONTROL_UNPROTECTED === 'true' ? unprotectedTest : privateTest;
const { renderTitleForCall } = require(
  resolve(
    dirname(require.resolve('playwright-core/package.json')),
    'lib/utils/isomorphic/protocolFormatter.js',
  ),
);
test.afterEach(async ({}, info) => sanitizeTestErrors(info));

test('successful sensitive step metadata and worker output are not emitted', async ({}, info) => {
  const title = renderTitleForCall({ type: 'Frame', method: 'fill', params: { value: marker } });
  expect(title.includes(marker)).toBe(true); // reproduces the pinned library's original leak
  await test.step(title, async () => {
    console.log(marker);
    console.error(marker);
  });
  writeFileSync(
    info.outputPath('control.json'),
    JSON.stringify({ originalFillTitleContainsMarker: true }),
  );
});

test('failed sensitive call error and automatic context are redacted', async () => {
  // This control must fail in Playwright; it is not an acceptance test or a product skip.
  test.fail(true, 'Intentional failure exercises raw diagnostics without a browser');
  await test.step(`Fill "${marker}"`, async () => {
    throw new Error(`locator.fill failed: ${marker}`);
  });
});

const setupFailure = test.extend<{ brokenSetup: void }>({
  brokenSetup: [
    async () => {
      throw new Error(`fixture setup failure: ${marker}`);
    },
    { auto: true },
  ],
});
setupFailure.fail(
  'failed fixture setup diagnostics are redacted before any browser',
  async () => {},
);

const lateFailure = test.extend<{ lateFailure: void }>({
  lateFailure: [
    async ({}, use) => {
      await use();
      throw new Error(`late fixture failure: ${marker}`);
    },
    {},
  ],
});

lateFailure.fail(
  'late fixture diagnostics are safe before the producer attachment',
  async ({ lateFailure }, info) => {
    void lateFailure;
    const originalWrite = fsPromises.writeFile;
    const artifact = info.outputPath('error-context.md');
    // Test-only interception observes the ACTUAL vendor write before _attach/reporter.
    // No vendor file is changed, no browser is requested, and only public-marker booleans are saved.
    fsPromises.writeFile = async (...args: Parameters<typeof originalWrite>) => {
      await originalWrite(...args);
      if (String(args[0]) !== artifact) return;
      fsPromises.writeFile = originalWrite;
      const observation = {
        stage: 'AUTOMATIC_CONTEXT_BEFORE_ATTACHMENT',
        markerAbsent: !readFileSync(artifact, 'utf8').includes(marker),
        failureRetained: info.status === 'failed' && info.errors.length > 0,
        attachmentNotYetCreated: !info.attachments.some((item) => item.name === 'error-context'),
        interrupted: process.env.RCT_E2E_CONTROL_INTERRUPT === 'true',
      };
      writeFileSync(
        resolve(process.env.RCT_E2E_CONTROL_SUPERVISION_DIR!, 'producer-boundary.safe.json'),
        JSON.stringify(observation),
      );
      if (observation.interrupted) {
        process.kill(process.pid, 'SIGTERM');
        // Do not resolve the vendor write await before the worker actually terminates.
        await new Promise(() => {});
      }
    };
  },
);

if (process.env.RCT_E2E_CONTROL_MISSING_GUARD === 'true') {
  const operation = privateTest.extend<{ protectedOperation: void }>({
    protectedOperation: async ({}, use) => {
      writeFileSync(
        resolve(process.env.RCT_E2E_CONTROL_SUPERVISION_DIR!, 'explicit-operation.safe.json'),
        JSON.stringify({ explicitOperationStarted: true }),
      );
      await use();
    },
  });
  operation.fail(
    'privacy guard rejects before an explicit operation fixture',
    async ({ protectedOperation }) => {
      void protectedOperation;
    },
  );
}

test('revoked-array counterexample fails the actual permission assertion', async () => {
  const leaked = [{ code: 'MARK_ATTENDANCE', label: 'Отмечать посещаемость' }];
  expect(assistantPermissionCodes(leaked)).toContain('MARK_ATTENDANCE');
  expect(() => expect(assistantPermissionCodes(leaked)).toEqual([])).toThrow();
  expect(assistantPermissionCodes([])).toEqual([]);
  expect(() => assistantPermissionCodes({ permissions: [] })).toThrow();
});

test('only the canonical dedicated reporter passes before credential creation', async ({}, info) => {
  const baseline: WorkerInfo = {
    config: info.config,
    project: info.project,
    parallelIndex: info.parallelIndex,
    workerIndex: info.workerIndex,
  };
  const accepts = (candidate: WorkerInfo) => {
    try {
      requirePrivateArtifacts(candidate);
      return true;
    } catch {
      return false;
    }
  };
  const alternateDir = mkdtempSync(join(tmpdir(), 'rct-reporter-identity-'));
  try {
    const alternatePath = join(alternateDir, 'safe-reporter.ts');
    writeFileSync(alternatePath, 'export default class AlternateReporter {}');
    const controls = {
      canonicalReporterAccepted: accepts(baseline),
      sameBasenameAlternateRejected: !accepts({
        ...baseline,
        config: { ...baseline.config, reporter: [[require.resolve(alternatePath)]] },
      }),
      extraReporterRejected: !accepts({
        ...baseline,
        config: { ...baseline.config, reporter: [...baseline.config.reporter, ['html']] },
      }),
      traceRejected: !accepts({
        ...baseline,
        project: { ...baseline.project, use: { ...baseline.project.use, trace: 'on' } },
      }),
      videoRejected: !accepts({
        ...baseline,
        project: { ...baseline.project, use: { ...baseline.project.use, video: 'on' } },
      }),
      screenshotRejected: !accepts({
        ...baseline,
        project: { ...baseline.project, use: { ...baseline.project.use, screenshot: 'on' } },
      }),
      missingSnapshotGuardRejected: false,
      wrongSnapshotGuardRejected: false,
    };
    const snapshotGuard = process.env.PLAYWRIGHT_NO_COPY_PROMPT;
    try {
      delete process.env.PLAYWRIGHT_NO_COPY_PROMPT;
      controls.missingSnapshotGuardRejected = !accepts(baseline);
      process.env.PLAYWRIGHT_NO_COPY_PROMPT = '0';
      controls.wrongSnapshotGuardRejected = !accepts(baseline);
    } finally {
      process.env.PLAYWRIGHT_NO_COPY_PROMPT = snapshotGuard;
    }
    writeFileSync(info.outputPath('guard-control.json'), JSON.stringify(controls));
    expect(controls.canonicalReporterAccepted).toBe(true);
    expect(controls.sameBasenameAlternateRejected).toBe(true);
    expect(controls.extraReporterRejected).toBe(true);
    expect(controls.traceRejected).toBe(true);
    expect(controls.videoRejected).toBe(true);
    expect(controls.screenshotRejected).toBe(true);
    expect(controls.missingSnapshotGuardRejected).toBe(true);
    expect(controls.wrongSnapshotGuardRejected).toBe(true);
  } finally {
    rmSync(alternateDir, { recursive: true, force: true });
  }
});
